import { fireEvent, screen } from '@testing-library/dom';
import { render } from '@testing-library/react';
import React from 'react';
import { format } from 'date-fns';
import { Calendar } from '../..';
import { setUTCHoursForDate } from './utils/setUTCHoursForDate';

const calendarProps = {
  hightlightedDates: [
    {
      theme: 'gray',
      caption: 'First',
      dates: [new Date(2022, 9, 29), new Date(2022, 9, 28), new Date(2022, 9, 27)],
    },
    {
      theme: 'cyan',
      caption: 'Second',
      dates: [new Date(1664217427000)],
    },
  ],
  markedDates: [
    new Date(2022, 9, 29),
    new Date(2022, 9, 28),
    new Date(2022, 9, 15),
    new Date(1664217427000),
  ],
};

describe('Calendar', () => {
  it('should render without crashing', () => {
    render(<Calendar {...calendarProps} numberOfMonths={2} />);
    expect(screen.getByText(format(new Date(), 'MMMM yyyy'))).toBeInTheDocument();
  });

  it('should render with range mode without crashing', () => {
    render(<Calendar {...calendarProps} mode="range" />);
    expect(screen.getByText(format(new Date(), 'MMMM yyyy'))).toBeInTheDocument();
  });

  it('should change the month when the previous arrow is clicked to the previous month', () => {
    render(<Calendar />);
    fireEvent.click(screen.getByTestId('previous-calendar-month-button'));
    const expectMonthDate = new Date();
    expectMonthDate.setDate(1);
    expectMonthDate.setMonth(expectMonthDate.getMonth() - 1);
    expect(screen.getByText(format(expectMonthDate, 'MMMM yyyy'))).toBeInTheDocument();
  });

  it('should change the month when the previous arrow is clicked to the next month', () => {
    render(<Calendar />);
    fireEvent.click(screen.getByTestId('next-calendar-month-button'));
    const expectMonthDate = new Date();
    expectMonthDate.setDate(1);
    expectMonthDate.setMonth(expectMonthDate.getMonth() + 1);
    expect(screen.getByText(format(expectMonthDate, 'MMMM yyyy'))).toBeInTheDocument();
  });

  it('should change the hour of timestamp on date selection', () => {
    const onChangeMock = jest.fn();
    const onSaveMock = jest.fn();
    const expectedDate = setUTCHoursForDate(new Date());
    const today = expectedDate.getDate();

    render(<Calendar onChange={onChangeMock} onSaveMock={onSaveMock} />);
    const allMatchesTodayDate = screen.getAllByText(today);
    const todayIndex = today < 15 ? 0 : allMatchesTodayDate.length - 1;
    fireEvent.click(allMatchesTodayDate[todayIndex]);
    expect(onChangeMock).toHaveBeenCalledWith(expectedDate);
  });
});
